-- Peru deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (SUNAT / OSE)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los requisitos de OSE/PSE, las reglas de validación empresarial y el reporte sectorial específico continúan evolucionando — confirme los requisitos actuales directamente con la SUNAT antes de construir una integración.', 'El despliegue de Perú siguió el patrón latinoamericano clásico — primero los mayores contribuyentes, luego una ampliación constante hasta cubrir esencialmente toda la economía.', 'CPE es un término genérico amplio — Perú abarca muchos más tipos de documentos bajo este único marco que la mayoría de los países de este rastreador.', 'El modelo de Perú tiene una característica genuinamente distintiva: los OSE no son meros intermediarios — poseen la misma autoridad legal de validación que la propia SUNAT.', 'Verificar el estado de autorización de su proveedor importa aquí más que en la mayoría de los países — los proveedores PSE/OSE no autorizados emiten documentos sin ninguna validez legal.', 'Los profesionales describen el marco de facturación y reporte electrónico de Perú como integral y tecnológicamente avanzado — el riesgo práctico es la invalidez, no solo las multas.' FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (SUNAT / OSE)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. OSE-/PSE-Anforderungen, Geschäftsvalidierungsregeln und sektorspezifische Meldepflichten entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der SUNAT, bevor Sie eine Integration aufbauen.', 'Perus Einführung folgte dem klassischen lateinamerikanischen Muster — zuerst die größten Steuerpflichtigen, dann eine stetige Ausweitung, bis im Wesentlichen die gesamte Wirtschaft erfasst war.', 'CPE ist ein weit gefasster Oberbegriff — Peru deckt unter diesem einen Rahmenwerk weit mehr Dokumenttypen ab als die meisten Länder in diesem Tracker.', 'Perus Modell hat ein wirklich charakteristisches Merkmal: OSEs sind keine bloßen Vermittler — sie besitzen dieselbe rechtliche Validierungsbefugnis wie die SUNAT selbst.', 'Die Überprüfung des Autorisierungsstatus Ihres Anbieters ist hier wichtiger als in den meisten Ländern — nicht autorisierte PSE-/OSE-Anbieter stellen Dokumente ohne jegliche rechtliche Gültigkeit aus.', 'Perus E-Rechnungs- und E-Reporting-Rahmenwerk wird von Praktikern als umfassend und technologisch fortschrittlich beschrieben — das praktische Risiko ist Ungültigkeit, nicht nur Geldstrafen.' FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (SUNAT / OSE)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les exigences OSE/PSE, les règles de validation commerciale et la déclaration sectorielle spécifique continuent d''évoluer — confirmez les exigences actuelles directement auprès de la SUNAT avant de construire une intégration.', 'Le déploiement du Pérou a suivi le schéma latino-américain classique — d''abord les plus grands contribuables, puis un élargissement constant jusqu''à couvrir essentiellement toute l''économie.', 'Le CPE est un terme générique large — le Pérou couvre bien plus de types de documents sous ce cadre unique que la plupart des pays de ce tracker.', 'Le modèle péruvien présente une caractéristique véritablement distinctive : les OSE ne sont pas de simples intermédiaires — ils détiennent la même autorité légale de validation que la SUNAT elle-même.', 'Vérifier le statut d''autorisation de votre fournisseur compte plus ici que dans la plupart des pays — les fournisseurs PSE/OSE non autorisés émettent des documents sans aucune validité légale.', 'Le cadre de facturation et de déclaration électroniques du Pérou est décrit par les praticiens comme complet et technologiquement avancé — le risque pratique est l''invalidité, pas seulement les amendes.' FROM countries WHERE name_en = 'Peru';

