INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato', '[["Sintaxis", "XML UBL 2.1, exclusivamente desde marzo de 2019"], ["Codificación", "UTF-8"], ["Estándar de firma", "X.509 v3"], ["Integridad", "Hash SHA-256"]]', 'El artículo 2 del reglamento es explícito: solo los documentos que cumplan simultáneamente todas estas características técnicas son legalmente válidos — el cumplimiento parcial no cuenta.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Format', '[["Syntax", "UBL-2.1-XML, ausschließlich seit März 2019"], ["Kodierung", "UTF-8"], ["Signaturstandard", "X.509 v3"], ["Integrität", "SHA-256-Hash"]]', 'Artikel 2 der Durchführungsverordnung ist eindeutig: Nur Dokumente, die alle diese technischen Merkmale gleichzeitig erfüllen, sind rechtsgültig — teilweise Einhaltung zählt nicht.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format', '[["Syntaxe", "XML UBL 2.1, exclusivement depuis mars 2019"], ["Encodage", "UTF-8"], ["Norme de signature", "X.509 v3"], ["Intégrité", "Hachage SHA-256"]]', 'L''article 2 du règlement d''application est explicite : seuls les documents remplissant simultanément toutes ces caractéristiques techniques sont légalement valides — une conformité partielle ne compte pas.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Familia de documentos CPE', '[["Ventas", "Facturas, boletas de venta"], ["Ajustes", "Notas de crédito y débito"], ["Relacionados con impuestos", "Comprobantes de retención y percepción"], ["Otros", "Recibos de servicios públicos, liquidaciones de compra electrónicas, GRE (guías de remisión/transporte)"]]', 'Elegir el tipo correcto de CPE para su transacción específica es fundamental — el tipo incorrecto puede socavar su capacidad de deducir gastos o reclamar créditos fiscales, no solo crear un dolor de cabeza administrativo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'CPE-Dokumentenfamilie', '[["Verkäufe", "Rechnungen, boletas de venta"], ["Anpassungen", "Gutschriften und Lastschriften"], ["Steuerbezogen", "Einbehaltungs- und Wahrnehmungsbelege"], ["Sonstige", "Belege für öffentliche Dienstleistungen, elektronische Kaufabrechnungen, GRE (Versand-/Transportbegleitscheine)"]]', 'Die Wahl des korrekten CPE-Typs für Ihre spezifische Transaktion ist entscheidend — der falsche Typ kann Ihre Fähigkeit untergraben, Ausgaben abzusetzen oder Steuergutschriften geltend zu machen, nicht nur eine Papierkram-Belastung darstellen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Famille de documents CPE', '[["Ventes", "Factures, boletas de venta"], ["Ajustements", "Notes de crédit et de débit"], ["Liés à la fiscalité", "Justificatifs de retenue et de perception"], ["Autres", "Reçus de services publics, règlements d''achat électroniques, GRE (guides d''expédition/transport)"]]', 'Choisir le bon type de CPE pour votre transaction spécifique est essentiel — un type incorrect peut compromettre votre capacité à déduire des dépenses ou à réclamer des crédits de TVA, pas seulement créer un casse-tête administratif.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Nomenclatura de documentos', '[["Ejemplos", "\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Se trata de nombres de documentos formales y específicos definidos en la normativa — acierte tanto en la etiqueta como en el contenido.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Dokumentbenennung', '[["Beispiele", "\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Dies sind formale, spezifische Dokumentnamen, die in der Verordnung festgelegt sind — achten Sie sowohl auf die Bezeichnung als auch auf den korrekten Inhalt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Nomenclature des documents', '[["Exemples", "\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Il s''agit de noms de documents formels et spécifiques définis par la réglementation — veillez à obtenir à la fois le bon libellé et le bon contenu.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Archivo', '[["Período de conservación", "5 años como mínimo, desde el primer día del año siguiente"], ["Qué conservar", "XML, CDR, avisos de rechazo, resúmenes diarios"]]', 'La obligación exacta de conservación varía ligeramente según el régimen del contribuyente — confirme su regla específica en lugar de asumir que se aplica uniformemente una cifra fija de 5 años.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "Mindestens 5 Jahre, ab dem ersten Tag des Folgejahres"], ["Was aufzubewahren ist", "XML, CDR, Ablehnungsbenachrichtigungen, Tageszusammenfassungen"]]', 'Die genaue Aufbewahrungspflicht variiert leicht je nach Steuerpflichtigenregime — bestätigen Sie Ihre spezifische Regel, statt anzunehmen, dass eine pauschale 5-Jahres-Frist einheitlich gilt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Archivage', '[["Période de conservation", "5 ans minimum, à partir du premier jour de l''année suivante"], ["Ce qu''il faut conserver", "XML, CDR, avis de rejet, résumés quotidiens"]]', 'L''obligation exacte de conservation varie légèrement selon le régime du contribuable — vérifiez votre règle spécifique plutôt que de présumer qu''un chiffre fixe de 5 ans s''applique uniformément.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Los tres roles', '[["PSE", "Opcional — construye y firma el XML en nombre del contribuyente"], ["OSE", "Valida el CPE con la misma autoridad legal que la SUNAT — no es un mero intermediario"], ["SEE", "Sistema propio de emisión electrónica directa de la SUNAT"]]', 'Vale la pena interiorizar esto: la validación de un OSE es legalmente equivalente a que la propia SUNAT la valide directamente. Pero un OSE no puede validar documentos de entrega/transporte — esa distinción importa para las empresas con gran actividad logística.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die drei Rollen', '[["PSE", "Optional — erstellt und signiert das XML im Namen des Steuerpflichtigen"], ["OSE", "Validiert die CPE mit derselben rechtlichen Befugnis wie die SUNAT — kein bloßer Vermittler"], ["SEE", "Eigenes direktes elektronisches Ausstellungssystem der SUNAT"]]', 'Das sollte man verinnerlichen: Die Validierung eines OSE ist rechtlich gleichbedeutend mit einer direkten Validierung durch die SUNAT. Ein OSE kann jedoch keine Liefer-/Transportdokumente validieren — diese Unterscheidung ist für logistiklastige Unternehmen wichtig.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Les trois rôles', '[["PSE", "Facultatif — construit et signe le XML au nom du contribuable"], ["OSE", "Valide le CPE avec la même autorité légale que la SUNAT — pas un simple intermédiaire"], ["SEE", "Propre système d''émission électronique directe de la SUNAT"]]', 'Cela mérite d''être intériorisé : la validation d''un OSE équivaut légalement à une validation directe par la SUNAT. Mais un OSE ne peut pas valider les documents de livraison/transport — cette distinction compte pour les entreprises à forte activité logistique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Elegir su nivel de operación', '[["SEE-SOL", "Bajo volumen (<1.000/mes), portal web gratuito"], ["PSE", "Volumen medio, facilitación externa"], ["OSE", "Alto volumen, integración con su propio ERP"], ["SEE Facturador", "Empresas sin capacidad interna de desarrollo técnico"]]', 'Ajuste su nivel a su volumen real de transacciones y capacidad técnica — sobredimensionar una empresa de bajo volumen con una integración OSE completa desperdicia un esfuerzo que una cuenta gratuita del portal SOL habría cubierto.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Wahl Ihrer Betriebsstufe', '[["SEE-SOL", "Geringes Volumen (<1.000/Monat), kostenloses Webportal"], ["PSE", "Mittleres Volumen, externe Unterstützung"], ["OSE", "Hohes Volumen, eigene ERP-Integration"], ["SEE Facturador", "Unternehmen ohne interne technische Entwicklungskapazität"]]', 'Passen Sie Ihre Stufe an Ihr tatsächliches Transaktionsvolumen und Ihre technische Kapazität an — ein Unternehmen mit geringem Volumen mit einer vollständigen OSE-Integration zu überdimensionieren, verschwendet Aufwand, den ein kostenloses SOL-Portalkonto abgedeckt hätte.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Choisir votre niveau opérationnel', '[["SEE-SOL", "Faible volume (<1 000/mois), portail web gratuit"], ["PSE", "Volume moyen, facilitation externe"], ["OSE", "Volume élevé, intégration ERP propre"], ["SEE Facturador", "Entreprises sans capacité de développement technique interne"]]', 'Adaptez votre niveau à votre volume de transactions réel et à votre capacité technique — sur-équiper une entreprise à faible volume avec une intégration OSE complète gaspille des efforts qu''un compte de portail SOL gratuit aurait couverts.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Un atajo permitido pero arriesgado', '[["Entrega asíncrona", "Técnicamente permitida — enviar al comprador antes de la validación de SUNAT/OSE"], ["Riesgo", "Explícitamente señalado como práctica arriesgada por los profesionales"]]', 'Que la normativa permita enviar una factura antes de que se complete la validación no la convierte en una buena práctica — un documento posteriormente rechazado crea problemas reales de conciliación para ambas partes.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Eine erlaubte, aber riskante Abkürzung', '[["Asynchrone Zustellung", "Technisch erlaubt — Versand an den Käufer vor der SUNAT/OSE-Validierung"], ["Risiko", "Von Praktikern ausdrücklich als riskante Praxis eingestuft"]]', 'Nur weil die Verordnung den Versand einer Rechnung vor Abschluss der Validierung erlaubt, macht das dies nicht zu guter Praxis — ein anschließend abgelehntes Dokument verursacht für beide Parteien echte Abstimmungsprobleme.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Un raccourci autorisé mais risqué', '[["Livraison asynchrone", "Techniquement autorisée — envoi à l''acheteur avant la validation SUNAT/OSE"], ["Risque", "Explicitement signalé comme pratique risquée par les praticiens"]]', 'Ce n''est pas parce que la réglementation permet d''envoyer une facture avant la fin de la validation que c''est une bonne pratique — un document ultérieurement rejeté crée de vrais problèmes de rapprochement pour les deux parties.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de compensación', NULL, 'El CDR (Constancia de Recepción) es el equivalente peruano de un recibo de compensación — es lo que confirma que el documento tiene plena validez legal y fiscal, similar en función al UPO de Polonia o a la Ricevuta di Consegna de Italia.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der Clearing-Ablauf', NULL, 'Die CDR (Constancia de Recepción) ist Perus Äquivalent zu einer Clearing-Quittung — sie bestätigt, dass das Dokument volle rechtliche und steuerliche Gültigkeit besitzt, funktional ähnlich zu Polens UPO oder Italiens Ricevuta di Consegna.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux de contrôle', NULL, 'Le CDR (Constancia de Recepción) est l''équivalent péruvien d''un accusé de contrôle — c''est ce qui confirme que le document a pleine validité légale et fiscale, fonctionnellement similaire à l''UPO polonais ou à la Ricevuta di Consegna italienne.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru';

