INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'fr', '3. Soumettre à l''OSE/SUNAT' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru' AND dls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'es', '4. Validar contra más de 100 reglas' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru' AND dls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'de', '4. Gegen 100+ Regeln validieren' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru' AND dls.sort_order = 3;
