INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'de', '5. CDR wird ausgestellt' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru' AND dls.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'fr', '5. Le CDR est émis' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Peru' AND dls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga su RUC y regístrese como emisor electrónico', 'Su número de Registro Único de Contribuyentes y el registro como emisor electrónico ante la SUNAT son los requisitos previos para todo lo que sigue.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie Ihre RUC und registrieren Sie sich als elektronischer Aussteller', 'Ihre Registro-Único-de-Contribuyentes-Nummer und die Registrierung als elektronischer Aussteller bei der SUNAT sind die Voraussetzungen für alles Weitere.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez votre RUC et inscrivez-vous en tant qu''émetteur électronique', 'Votre numéro de Registro Único de Contribuyentes et votre inscription en tant qu''émetteur électronique auprès de la SUNAT sont les conditions préalables à tout ce qui suit.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su nivel de operación según el volumen', 'SEE-SOL para bajo volumen, PSE para volumen medio con ayuda externa, OSE para alto volumen con su propio ERP, o SEE Facturador si carece de capacidad de desarrollo interna.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihre Betriebsstufe basierend auf dem Volumen', 'SEE-SOL für geringes Volumen, PSE für mittleres Volumen mit externer Unterstützung, OSE für hohes Volumen mit eigenem ERP, oder SEE Facturador, falls Sie keine interne Entwicklungskapazität haben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre niveau opérationnel selon le volume', 'SEE-SOL pour un faible volume, PSE pour un volume moyen avec aide externe, OSE pour un volume élevé avec votre propre ERP, ou SEE Facturador si vous manquez de capacité de développement interne.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga un certificado digital X.509 v3 válido', 'Esto es lo que autentica y firma cada CPE que emita.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie ein gültiges X.509-v3-Digitalzertifikat', 'Dies ist es, was jede von Ihnen ausgestellte CPE authentifiziert und signiert.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez un certificat numérique X.509 v3 valide', 'C''est ce qui authentifie et signe chaque CPE que vous émettez.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Verifique cualquier proveedor PSE/OSE contra la lista actual de la SUNAT', 'Consulte cpe.sunat.gob.pe antes de contratar — la salida de un proveedor no autorizado no tiene validez fiscal legal alguna, sin importar lo correcto que parezca el XML.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Überprüfen Sie jeden PSE-/OSE-Anbieter anhand der aktuellen Liste der SUNAT', 'Prüfen Sie cpe.sunat.gob.pe vor Vertragsabschluss — die Ausgabe eines nicht autorisierten Anbieters hat keine steuerliche Rechtsgültigkeit, unabhängig davon, wie korrekt das XML aussieht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez tout fournisseur PSE/OSE par rapport à la liste actuelle de la SUNAT', 'Consultez cpe.sunat.gob.pe avant de contracter — la production d''un fournisseur non autorisé n''a aucune validité fiscale légale, peu importe à quel point le XML semble correct.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure la generación de XML UBL 2.1 con integridad SHA-256', 'Confirme que su sistema produce salidas conformes antes de su primer envío en producción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Konfigurieren Sie die UBL-2.1-XML-Erzeugung mit SHA-256-Integrität', 'Bestätigen Sie, dass Ihr System konforme Ausgaben erzeugt, bevor Sie Ihre erste Produktionsübermittlung vornehmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Configurez la génération XML UBL 2.1 avec intégrité SHA-256', 'Confirmez que votre système produit une sortie conforme avant votre première soumission en production.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Construya un flujo de trabajo de almacenamiento y conciliación de CDR', 'Cada CPE emitido necesita su CDR correspondiente conservado junto a él — trate el par como un único registro de cumplimiento, no dos archivos separados.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bauen Sie einen CDR-Speicher- und Abstimmungsworkflow auf', 'Jede ausgestellte CPE benötigt ihre entsprechende CDR, die zusammen mit ihr aufbewahrt wird — behandeln Sie das Paar als einen einzigen Compliance-Datensatz, nicht als zwei separate Dateien.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Construisez un flux de travail de stockage et de rapprochement des CDR', 'Chaque CPE émis a besoin que son CDR correspondant soit conservé à ses côtés — traitez la paire comme un seul enregistrement de conformité, pas deux fichiers séparés.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Evite los atajos de entrega asíncrona', 'Espere la validación de SUNAT/OSE antes de entregar al comprador, aunque la normativa técnicamente permita enviar primero.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Vermeiden Sie asynchrone Zustellabkürzungen', 'Warten Sie auf die SUNAT/OSE-Validierung, bevor Sie an den Käufer liefern, auch wenn die Verordnung technisch das vorherige Versenden erlaubt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Évitez les raccourcis de livraison asynchrone', 'Attendez la validation SUNAT/OSE avant de livrer à l''acheteur, même si la réglementation permet techniquement d''envoyer en premier.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Peru' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🚫 La validez, no solo las sanciones, es el riesgo principal', NULL, NULL, 'Un CPE que no supera la validación de OSE/SUNAT simplemente no es un documento fiscal legalmente válido — esto afecta la capacidad del comprador para deducir el gasto o reclamar el crédito de IVA, que a menudo es una consecuencia comercial más aguda que cualquier multa administrativa.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🚫 Gültigkeit, nicht nur Strafen, ist das Kernrisiko', NULL, NULL, 'Eine CPE, die die OSE-/SUNAT-Validierung nicht besteht, ist schlicht kein rechtsgültiges Steuerdokument — dies beeinträchtigt die Fähigkeit des Käufers, die Ausgabe abzusetzen oder die Umsatzsteuergutschrift geltend zu machen, was oft eine schärfere geschäftliche Konsequenz ist als jede Verwaltungsstrafe.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🚫 La validité, pas seulement les sanctions, est le risque central', NULL, NULL, 'Un CPE qui échoue à la validation OSE/SUNAT n''est tout simplement pas un document fiscal légalement valide — cela affecte la capacité de l''acheteur à déduire la dépense ou à réclamer un crédit de TVA, ce qui constitue souvent une conséquence commerciale plus grave que toute amende administrative.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🛰️ Reporte electrónico relacionado', NULL, NULL, 'Perú también gestiona reportes periódicos de retención/percepción de IVA (a través de los comprobantes de retención/percepción dentro de la familia CPE) y canaliza cada vez más el reporte específico de sectores — como el nuevo sistema de boletos aéreos — a través de la misma infraestructura electrónica.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🛰️ Verwandte elektronische Meldungen', NULL, NULL, 'Peru führt außerdem periodische USt-Einbehaltungs-/Wahrnehmungsberichte (über die comprobantes de retención/percepción innerhalb der CPE-Familie) und leitet zunehmend sektorspezifische Meldungen — wie das neue Flugticket-System — über dieselbe elektronische Infrastruktur.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🛰️ Déclarations électroniques connexes', NULL, NULL, 'Le Pérou gère également des déclarations périodiques de retenue/perception de TVA (via les comprobantes de retención/percepción au sein de la famille CPE) et canalise de plus en plus les déclarations sectorielles spécifiques — comme le nouveau système de billets d''avion — via la même infrastructure électronique.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🖥️ Portal SIRE', NULL, NULL, 'La documentación y herramientas oficiales de la SUNAT, incluido el portal SIRE, son el punto de referencia principal para las especificaciones técnicas actuales — consúltelo directamente para todo lo que no esté cubierto por la propia documentación de su proveedor PSE/OSE.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🖥️ SIRE-Portal', NULL, NULL, 'Die offizielle Dokumentation und die Tools der SUNAT, einschließlich des SIRE-Portals, sind die primäre Referenzquelle für aktuelle technische Spezifikationen — konsultieren Sie diese direkt für alles, was nicht durch die eigene Dokumentation Ihres PSE-/OSE-Anbieters abgedeckt ist.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🖥️ Portail SIRE', NULL, NULL, 'La documentation et les outils officiels de la SUNAT, y compris le portail SIRE, constituent la référence principale pour les spécifications techniques actuelles — consultez-les directement pour tout ce qui n''est pas couvert par la propre documentation de votre fournisseur PSE/OSE.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📦 Limitaciones de los OSE', NULL, NULL, 'Recuerde que en algunas configuraciones del sistema los OSE no están autorizados a validar documentos de entrega o transporte — confirme este límite con su proveedor específico si su negocio implica logística o guías de remisión (GRE).', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📦 Einschränkungen der OSEs', NULL, NULL, 'Denken Sie daran, dass OSEs in einigen Systemkonfigurationen keine Liefer- oder Transportdokumente validieren dürfen — bestätigen Sie diese Grenze mit Ihrem spezifischen Anbieter, wenn Ihr Unternehmen Logistik oder Versandbegleitscheine (GRE) betrifft.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📦 Limitations des OSE', NULL, NULL, 'Rappelez-vous que dans certaines configurations système, les OSE ne sont pas autorisés à valider les documents de livraison ou de transport — confirmez cette limite avec votre fournisseur spécifique si votre entreprise implique de la logistique ou des guides d''expédition (GRE).', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'SUNAT' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Peru' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'SUNAT' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Peru' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'SUNAT' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Peru' AND dp.sort_order = 0;
